draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  for (let i = 0; i < 8; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + Math.cos(i) * 30, H/2 + Math.sin(i) * 30, 5, 0, 2 * Math.PI);
    ctx.fillStyle = 'black';
    ctx.fill();
  }
  ctx.restore();
}
